NEW_FILES = {'tests/service/test_prepare_environment.py': '"""The panel prepares the tools\' Python itself (0.244.0, the factory\'s roadmap 311, increment 2).\n\nIncrement 1\'s dock named the blocker a new user meets first on this machine -- the launcher runs the factory on\nBlender\'s own Python, which cannot import PIL, pygltflib or jsonschema -- and its fix was `factory setup --venv`, a\nterminal step. `prepare_environment` is that step as a service operation. These tests drive it with a fake `run`\nso nothing is downloaded; FAILS ON 0.243.0.\n"""\nimport json\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom packages.service import operations  # noqa: E402\nfrom packages.service.worker import EventSink, RequestError  # noqa: E402\n\n\ndef _factory(tmp_path, monkeypatch, made="ok"):\n    from packages.tools import discovery, interpreter\n    monkeypatch.setattr(discovery, "factory_root", lambda start=None: tmp_path)\n    (tmp_path / discovery.LOCAL_FILE).write_text(json.dumps({\n        "schema": discovery.LOCAL_SCHEMA, "blender_executable": "B", "godot_executable": "G",\n        "python_executable": ""}), encoding="utf-8")\n    calls = []\n\n    def fake_make_venv(root, base, *, run=None, timeout=1800):\n        calls.append((root, base))\n        # what make_venv\'s pip step does with the run it is given: a command whose output streams\n        run([sys.executable, "-c", "print(\'Collecting pillow\'); print(\'Successfully installed pillow\')"])\n        if made != "ok":\n            return "", made\n        return str(tmp_path / ".venv" / "Scripts" / "python.exe"), ""\n    monkeypatch.setattr(interpreter, "make_venv", fake_make_venv)\n    run_dir = tmp_path / "run"\n    run_dir.mkdir()\n    return EventSink(run_dir, "r", "prepare_environment"), calls\n\n\ndef test_it_makes_the_environment_records_it_and_streams_pip(tmp_path, monkeypatch):\n    from packages.tools import discovery\n    sink, calls = _factory(tmp_path, monkeypatch)\n    out = operations.prepare_environment({}, sink)\n    assert calls == [(tmp_path, sys.executable)]\n    rec = json.loads((tmp_path / discovery.LOCAL_FILE).read_text(encoding="utf-8"))\n    assert rec["python_executable"].endswith("python.exe")\n    assert (rec["blender_executable"], rec["godot_executable"]) == ("B", "G")       # kept\n    events = [json.loads(x) for x in sink.path.read_text(encoding="utf-8").splitlines()]\n    said = [e["message"] for e in events if e["stage"] == "install"]\n    assert "Collecting pillow" in said and "Successfully installed pillow" in said\n    assert "Successfully installed pillow" in (sink.path.parent / "pip.log").read_text(encoding="utf-8")\n    assert "checks" in out\n\n\ndef test_a_failed_install_is_a_refusal_that_says_which_step(tmp_path, monkeypatch):\n    from packages.tools import discovery\n    sink, _calls = _factory(tmp_path, monkeypatch, made="pip install pillow==12.3.0 exited 1")\n    with pytest.raises(RequestError) as e:\n        operations.prepare_environment({}, sink)\n    assert e.value.code == "environment_failed" and "pip install" in str(e.value)\n    rec = json.loads((tmp_path / discovery.LOCAL_FILE).read_text(encoding="utf-8"))\n    assert rec["python_executable"] == ""                                      # nothing recorded\n\n\ndef test_it_takes_no_arguments(tmp_path, monkeypatch):\n    sink, _calls = _factory(tmp_path, monkeypatch)\n    with pytest.raises(RequestError):\n        operations.prepare_environment({"force": True}, sink)\n\n\ndef test_the_tools_python_fix_names_the_button():\n    assert "Prepare environment" in operations.FIXES["tools_python"]\n'}
CHANGELOG = "## [0.244.0] - the panel prepares the tools' Python itself\n\n**Found by 0.243.0's panel on the walker's machine** (the factory's `docs/AUTHORING_LOOP.md`, increment 2;\nroadmap 311). Run through `factory.cmd`, the factory used Blender's own Python, which cannot import `PIL`,\n`pygltflib` or `jsonschema`. The dock named the problem, but its fix was `factory setup --venv`, a terminal step.\n\n### Added\n- **`prepare_environment`** (`packages/service/operations.py`): `setup --venv` as a service operation.\n  - It makes `<factory>/.venv` from the interpreter running the worker and installs `interpreter.PINNED` into it.\n    This is the one step that needs the network.\n  - It records the result as `python_executable` in `factory.local.json`, keeping the recorded Blender and Godot.\n  - pip's output, which `make_venv` sends to a terminal the panel does not have, streams instead as events and\n    into `pip.log` in the run directory (`_streaming_run`).\n  - A failed step is a refusal (`environment_failed`) naming it, with nothing recorded.\n- **Prepare environment (downloads once)** on the dock. It shows only when the tools' Python is what blocks, and\n  says it downloads before it is pressed. The `tools_python` check's fix now names it.\n\n### Tests\n- `tests/service/test_prepare_environment.py` (fails on 0.243.0), with a fake `make_venv` so nothing downloads:\n  records the environment and keeps Blender and Godot; streams pip's lines to events and `pip.log`; a failed\n  install refuses and records nothing; no arguments taken.\n- `apps/godot/tests/test_factory_dock.gd`: the button shows when the tools' Python blocks and hides when nothing\n  does.\n- Not run for real here: the download itself.\n\n"
OLD_VERSION, NEW_VERSION = '0.243.0', '0.244.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
